"use client"

import type { ReactNode } from "react"
import { GripVertical, Pencil, Trash2 } from "lucide-react"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge, type BadgeColor, type BadgeStyle } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { IconButton } from "@/components/ui/icon-button"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Rating } from "@/components/wunderui/rating"
import { Switch } from "@/components/ui/switch"
import { Popover, PopoverTrigger, PopoverContent } from "@/components/ui/popover"
import {
  NativeSelect,
  NativeSelectTrigger,
  NativeSelectValue,
  NativeSelectContent,
  NativeSelectItem,
} from "@/components/ui/native-select"
import { cn } from "@/lib/utils"

/**
 * The cell types of the Figma "Table Item" set. A data grid is mostly the same
 * handful of shapes repeated — a name over an email, a figure with its delta,
 * a control — so they live here as named pieces rather than being rebuilt in
 * every table.
 *
 * Two column heights recur: a single line of text sits in a 36 px row, a
 * two-line cell (user, company, product, address) in a 54 px one.
 */

const CELL_COLOR_SWATCHES = ["#12AFF0", "#A584F3", "#F3654A", "#FACA4A", "#1AD598", "#EC4899"]

/** Plain cell text. */
function TextCell({ children, className }: { children: ReactNode; className?: string }) {
  return <span className={cn("text-sm text-text-secondary", className)}>{children}</span>
}

/** Column header label — the only uppercase-weight cell in the set. */
function HeadingCell({ children, className }: { children: ReactNode; className?: string }) {
  return <span className={cn("text-xs font-semibold text-muted-foreground", className)}>{children}</span>
}

/** Name over email, with an avatar or a generic person glyph. */
function UserCell({
  name,
  email,
  avatarSrc,
  initials,
  avatarSize = "sm",
}: {
  name: string
  email?: string
  avatarSrc?: string
  initials?: string
  /** Avatar size; use "default" (36 px) when the cell shows name and email on two lines. */
  avatarSize?: "sm" | "xs" | "default" | "lg"
}) {
  return (
    <div className="flex items-center gap-3">
      <Avatar size={avatarSize}>
        {avatarSrc && <AvatarImage src={avatarSrc} alt="" />}
        <AvatarFallback>{initials ?? name.slice(0, 2).toUpperCase()}</AvatarFallback>
      </Avatar>
      <div className="flex flex-col">
        <span className="text-sm font-medium text-foreground">{name}</span>
        {email && <span className="text-xs text-muted-foreground">{email}</span>}
      </div>
    </div>
  )
}

/** Same shape as UserCell, but always a real avatar image or initials. */
function UserAvatarCell(props: Parameters<typeof UserCell>[0]) {
  return <UserCell {...props} />
}

function BadgeCell({
  label,
  color = "blue",
  badgeStyle = "light_border",
}: {
  label: string
  color?: BadgeColor
  badgeStyle?: BadgeStyle
}) {
  return (
    <Badge color={color} badgeStyle={badgeStyle}>
      {label}
    </Badge>
  )
}

function CurrencyCell({ value, currency = "$" }: { value: number; currency?: string }) {
  return (
    <span className="text-sm font-semibold text-muted-foreground">
      {currency}
      {value.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
    </span>
  )
}

/** A figure with its change — the delta is green when it is good news. */
function PerformanceCell({
  value,
  delta,
  good = true,
}: {
  value: string
  delta?: string
  good?: boolean
}) {
  return (
    <div className="flex items-baseline gap-2">
      <span className="text-sm font-semibold text-foreground">{value}</span>
      {delta && (
        <span className={cn("text-xs font-medium", good ? "text-text-success" : "text-text-error")}>{delta}</span>
      )}
    </div>
  )
}

/** Logo square, company name, domain. */
function CompanyCell({ name, domain, logoSrc }: { name: string; domain?: string; logoSrc?: string }) {
  return (
    <div className="flex items-center gap-3">
      <span className="size-8 shrink-0 overflow-hidden rounded-md bg-muted">
        {logoSrc && <img src={logoSrc} alt="" className="size-full object-cover" />}
      </span>
      <div className="flex flex-col">
        <span className="text-sm font-medium text-text-tertiary">{name}</span>
        {domain && <span className="text-xs text-muted-foreground">{domain}</span>}
      </div>
    </div>
  )
}

/** Thumbnail, product name, SKU. */
function ProductCell({ name, sku, imageSrc }: { name: string; sku?: string; imageSrc?: string }) {
  return (
    <div className="flex items-center gap-3">
      <span className="size-8 shrink-0 overflow-hidden rounded-md bg-muted">
        {imageSrc && <img src={imageSrc} alt="" className="size-full object-cover" />}
      </span>
      <div className="flex flex-col">
        <span className="text-sm font-medium text-foreground">{name}</span>
        {sku && <span className="text-xs text-muted-foreground">{sku}</span>}
      </div>
    </div>
  )
}

/** Street over city — two lines, no leading element. */
function AddressCell({ street, city }: { street: string; city?: string }) {
  return (
    <div className="flex flex-col">
      <span className="text-sm text-foreground">{street}</span>
      {city && <span className="text-xs text-muted-foreground">{city}</span>}
    </div>
  )
}

/** An icon beside a label. */
function IconTextCell({ icon, children }: { icon: ReactNode; children: ReactNode }) {
  return (
    <div className="flex items-center gap-3">
      <span className="flex shrink-0 items-center text-foreground [&_svg]:size-5">{icon}</span>
      <span className="text-sm text-foreground">{children}</span>
    </div>
  )
}

/** A small framed icon button beside a label. */
function IconButtonTextCell({
  icon,
  children,
  onClick,
  label,
}: {
  icon: ReactNode
  children: ReactNode
  onClick?: () => void
  label?: string
}) {
  return (
    <div className="flex items-center gap-3">
      <IconButton variant="plain" size="sm" aria-label={label ?? "Action"} onClick={onClick}>
        {icon}
      </IconButton>
      <span className="text-sm text-foreground">{children}</span>
    </div>
  )
}

/** A row of bare icon actions — edit, delete, view and the like. */
function ActionIconsCell({
  actions,
}: {
  actions: { icon: ReactNode; label: string; onClick?: () => void }[]
}) {
  return (
    <div className="flex items-center gap-4">
      {actions.map((action) => (
        <button
          key={action.label}
          type="button"
          aria-label={action.label}
          onClick={action.onClick}
          className="text-foreground transition-colors duration-fast ease-move hover:text-text-link [&_svg]:size-4"
        >
          {action.icon}
        </button>
      ))}
    </div>
  )
}

/** The filled call-to-action a row can carry. */
function CTAButtonCell({ children, onClick }: { children: ReactNode; onClick?: () => void }) {
  return (
    <Button variant="primary" size="sm" onClick={onClick}>
      {children}
    </Button>
  )
}

/** The quieter sibling of CTAButtonCell. */
function ButtonCell({ children, onClick }: { children: ReactNode; onClick?: () => void }) {
  return (
    <Button variant="plain" size="sm" onClick={onClick}>
      {children}
    </Button>
  )
}

/** Drag handle in front of the row label. */
function DragItemCell({ children }: { children: ReactNode }) {
  return (
    <div className="flex items-center gap-3">
      <GripVertical className="size-4 shrink-0 cursor-grab text-text-tertiary" />
      <span className="text-sm text-foreground">{children}</span>
    </div>
  )
}

function CheckItemCell({
  children,
  checked,
  onCheckedChange,
}: {
  children?: ReactNode
  checked?: boolean
  onCheckedChange?: (checked: boolean) => void
}) {
  return (
    <label className="flex items-center gap-3">
      <Checkbox checked={checked} onCheckedChange={onCheckedChange} />
      {children && <span className="text-sm text-foreground">{children}</span>}
    </label>
  )
}

function RadioItemCell({
  children,
  value,
  selected,
  onSelect,
}: {
  children?: ReactNode
  value: string
  selected?: string
  onSelect?: (value: string) => void
}) {
  return (
    <RadioGroup value={selected} onValueChange={(v) => onSelect?.(String(v))}>
      <label className="flex items-center gap-3">
        <RadioGroupItem value={value} />
        {children && <span className="text-sm text-foreground">{children}</span>}
      </label>
    </RadioGroup>
  )
}

function SwitchItemCell({
  children,
  checked,
  onCheckedChange,
}: {
  children?: ReactNode
  checked?: boolean
  onCheckedChange?: (checked: boolean) => void
}) {
  return (
    <label className="flex items-center gap-3">
      <Switch checked={checked} onCheckedChange={onCheckedChange} />
      {children && <span className="text-sm text-foreground">{children}</span>}
    </label>
  )
}

function ProgressCell({ value }: { value: number }) {
  return (
    <div className="flex items-center gap-2">
      <div className="h-1.5 w-20 overflow-hidden rounded-full bg-muted">
        <div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(100, Math.max(0, value))}%` }} />
      </div>
      <span className="text-xs font-medium text-muted-foreground">{value}%</span>
    </div>
  )
}

/** A dismissible label — the Figma "Tag" cell is a badge with a cross. */
function TagCell({
  label,
  color = "indigo",
  onRemove,
}: {
  label: string
  color?: BadgeColor
  onRemove?: () => void
}) {
  return (
    <Badge color={color} badgeStyle="light" shape="pill">
      {label}
      {onRemove && (
        <button type="button" aria-label={`Remove ${label}`} onClick={onRemove} className="-mr-0.5">
          <svg viewBox="0 0 12 12" className="size-3" aria-hidden>
            <path d="M3 3l6 6M9 3l-6 6" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
          </svg>
        </button>
      )}
    </Badge>
  )
}

/** Stars with the value beside them. */
function RatingCell({ value, max = 5 }: { value: number; max?: number }) {
  return <Rating value={value} max={max} label="right" readOnly />
}

function ActionItemsCell({ actions }: { actions: { label: string; onClick?: () => void; muted?: boolean }[] }) {
  return (
    <div className="flex items-center gap-4">
      {actions.map((a) => (
        <button
          key={a.label}
          type="button"
          onClick={a.onClick}
          className={cn("text-[13px] font-medium", a.muted ? "text-muted-foreground" : "text-text-link")}
        >
          {a.label}
        </button>
      ))}
    </div>
  )
}

function CellSwitch({
  checked,
  onCheckedChange,
  "aria-label": ariaLabel = "Toggle",
}: {
  checked: boolean
  onCheckedChange: (checked: boolean) => void
  /** Name for screen readers — a cell has no visible label of its own. */
  "aria-label"?: string
}) {
  return <Switch aria-label={ariaLabel} checked={checked} onCheckedChange={onCheckedChange} />
}

function CellSlider({ value, max = 100 }: { value: number; max?: number }) {
  // The bar is clamped to [0, max]: a negative value draws an empty bar, a value above max a full one, and a max
  // of 0 (or less) never divides by zero into a full bar. The number on the right shows the value as passed.
  const ratio = max > 0 && Number.isFinite(value) ? Math.min(1, Math.max(0, value / max)) : 0
  return (
    <div className="flex w-28 items-center gap-2">
      <div className="h-1 flex-1 overflow-hidden rounded-full bg-muted">
        <div
          className="h-full rounded-full bg-primary"
          style={{ width: `${ratio * 100}%` }}
        />
      </div>
      <span className="w-7 text-right text-xs text-text-tertiary">{value}</span>
    </div>
  )
}

function CellSelect({
  value,
  onValueChange,
  options,
  "aria-label": ariaLabel = "Choose a value",
}: {
  value: string
  onValueChange: (value: string) => void
  options: string[]
  /** Name for screen readers — a combobox is not named by its current value. */
  "aria-label"?: string
}) {
  return (
    <NativeSelect value={value} onValueChange={(v) => v && onValueChange(v)}>
      <NativeSelectTrigger aria-label={ariaLabel} className="h-8 w-32 px-2 text-xs">
        {/* A value longer than the 128 px trigger is cut with an ellipsis; the chevron stays inside the border. */}
        <NativeSelectValue className="min-w-0 flex-1 truncate text-left" />
      </NativeSelectTrigger>
      <NativeSelectContent>
        {options.map((option) => (
          <NativeSelectItem key={option} value={option}>
            {option}
          </NativeSelectItem>
        ))}
      </NativeSelectContent>
    </NativeSelect>
  )
}

function CellColorPicker({
  value,
  onValueChange,
  "aria-label": ariaLabel,
}: {
  value: string
  onValueChange: (value: string) => void
  /** Name for screen readers, such as "Label colour". The accessible name becomes "Label colour, #6366F1". Default: "Colour #6366F1. Choose a colour". */
  "aria-label"?: string
}) {
  return (
    <Popover>
      <PopoverTrigger
        aria-label={ariaLabel ? `${ariaLabel}, ${value}` : `Colour ${value}. Choose a colour`}
        className="size-6 rounded-full ring-1 ring-border ring-offset-2 ring-offset-card outline-none focus-ring"
        style={{ backgroundColor: value }}
      />
      <PopoverContent aria-label={ariaLabel ?? "Choose a colour"} className="w-auto p-2">
        <div className="grid grid-cols-6 gap-1.5">
          {CELL_COLOR_SWATCHES.map((swatch) => (
            <button
              key={swatch}
              type="button"
              aria-label={swatch}
              aria-pressed={value === swatch}
              onClick={() => onValueChange(swatch)}
              className={cn(
                "size-6 rounded-full transition-transform duration-fast ease-entrance hover:scale-110",
                value === swatch && "ring-2 ring-foreground ring-offset-2 ring-offset-popover"
              )}
              style={{ backgroundColor: swatch }}
            />
          ))}
        </div>
      </PopoverContent>
    </Popover>
  )
}

/** The default icon set for ActionIconsCell — edit, delete, view. */
const TABLE_ACTION_ICONS = {
  edit: <Pencil />,
  delete: <Trash2 />,
} as const

export {
  TextCell,
  HeadingCell,
  UserCell,
  UserAvatarCell,
  BadgeCell,
  CurrencyCell,
  PerformanceCell,
  CompanyCell,
  ProductCell,
  AddressCell,
  IconTextCell,
  IconButtonTextCell,
  ActionIconsCell,
  CTAButtonCell,
  ButtonCell,
  DragItemCell,
  CheckItemCell,
  RadioItemCell,
  SwitchItemCell,
  ProgressCell,
  TagCell,
  RatingCell,
  ActionItemsCell,
  CellSwitch,
  CellSlider,
  CellSelect,
  CellColorPicker,
  TABLE_ACTION_ICONS,
}

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import * as React from "react"
import { Select as SelectPrimitive } from "@base-ui/react/select"
import { Check, ChevronDown } from "lucide-react"
import { cn } from "@/lib/utils"
import { collectSelectItems } from "@/lib/select-items"

/**
 * Opens like the DropdownMenu: below the trigger (never over it, unlike a
 * macOS select), out of its anchor on --duration-base, quickly out again.
 */
const POPUP_MOTION =
  "origin-(--transform-origin) transition-[opacity,scale,translate] duration-base ease-entrance motion-reduce:transition-none " +
  "data-starting-style:opacity-0 data-starting-style:scale-(--scale-enter) " +
  "data-ending-style:opacity-0 data-ending-style:scale-(--scale-enter) data-ending-style:duration-fast data-ending-style:ease-exit " +
  "data-[side=bottom]:data-starting-style:-translate-y-(--travel-sm) data-[side=top]:data-starting-style:translate-y-(--travel-sm)"

function NativeSelect({ items, children, ...props }: SelectPrimitive.Root.Props<string>) {
  // Derive the value → label map from the items in `children` unless given,
  // so the trigger shows "Germany" for value "de" right away.
  const derived = React.useMemo(() => (items ? undefined : collectSelectItems(children)), [items, children])
  return (
    <SelectPrimitive.Root data-slot="native-select" items={items ?? (derived && derived.length > 0 ? derived : undefined)} {...props}>
      {children}
    </SelectPrimitive.Root>
  )
}

function NativeSelectTrigger({ className, children, ...props }: SelectPrimitive.Trigger.Props) {
  return (
    <SelectPrimitive.Trigger
      data-slot="native-select-trigger"
      className={cn(
        "flex h-(--field-md) w-full items-center justify-between gap-2 rounded-md border border-input bg-card px-3 text-sm text-foreground outline-none transition-colors duration-fast ease-entrance hover:border-text-muted focus-ring data-popup-open:border-primary data-disabled:pointer-events-none data-disabled:opacity-40 aria-invalid:border-error aria-invalid:focus-ring-error",
        className
      )}
      {...props}
    >
      {children}
      <SelectPrimitive.Icon>
        <ChevronDown className="size-4 text-text-tertiary" />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  )
}

function NativeSelectValue({ className, ...props }: SelectPrimitive.Value.Props) {
  // flex: an option with an icon shows the icon and the label side by side in the field; the placeholder is quieter than a value
  return <SelectPrimitive.Value data-slot="native-select-value" className={cn("flex min-w-0 items-center gap-2 data-placeholder:text-text-tertiary", className)} {...props} />
}

function NativeSelectContent({ className, children, ...props }: SelectPrimitive.Popup.Props) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Positioner className="isolate z-50 outline-none" side="bottom" align="start" sideOffset={4} alignItemWithTrigger={false}>
        <SelectPrimitive.Popup
          data-slot="native-select-content"
          className={cn(
            "z-50 max-h-(--available-height) w-(--anchor-width) min-w-32 overflow-y-auto rounded-lg bg-popover p-1 text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-none",
            // 2 px between two options (owner rule, 10 Nov 2026), so a highlighted or checked row never touches the next one.
            "[&_[role=option]+[role=option]]:mt-0.5",
            POPUP_MOTION,
            className
          )}
          {...props}
        >
          {children}
        </SelectPrimitive.Popup>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Portal>
  )
}

function NativeSelectItem({ className, children, ...props }: SelectPrimitive.Item.Props) {
  return (
    <SelectPrimitive.Item
      data-slot="native-select-item"
      className={cn(
        "relative flex cursor-default items-center rounded-md py-1.5 pr-8 pl-2 text-sm outline-hidden select-none data-highlighted:bg-bg-page data-highlighted:text-foreground",
        className
      )}
      {...props}
    >
      <SelectPrimitive.ItemText className="flex items-center gap-2">{children}</SelectPrimitive.ItemText>
      <span className="absolute right-2 flex items-center justify-center">
        <SelectPrimitive.ItemIndicator>
          <Check className="size-4" />
        </SelectPrimitive.ItemIndicator>
      </span>
    </SelectPrimitive.Item>
  )
}

export {
  NativeSelect,
  NativeSelectTrigger,
  NativeSelectValue,
  NativeSelectContent,
  NativeSelectItem,
}

import * as React from "react"

/**
 * Collects `{ value, label }` pairs from `<…Item value>label</…Item>` elements
 * anywhere in a Select's children, so `<Select.Value>` can show the label
 * before the popup has ever opened (Base UI otherwise renders the raw value).
 */
function collectSelectItems(children: React.ReactNode): { value: string; label: React.ReactNode }[] {
  const items: { value: string; label: React.ReactNode }[] = []
  const walk = (node: React.ReactNode) => {
    React.Children.forEach(node, (child) => {
      if (!React.isValidElement(child)) return
      const props = child.props as { value?: unknown; children?: React.ReactNode }
      if (typeof props.value === "string" && props.children !== undefined && typeof child.type !== "string") {
        items.push({ value: props.value, label: props.children })
      }
      if (props.children) walk(props.children)
    })
  }
  walk(children)
  return items
}

export { collectSelectItems }

"use client"

import * as React from "react"
import { Popover as PopoverPrimitive } from "@base-ui/react/popover"
import { cn } from "@/lib/utils"

function Popover({ ...props }: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />
}

function PopoverTrigger({ ...props }: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

function PopoverContent({
  className,
  sideOffset = 8,
  side,
  align,
  anchor,
  ...props
}: PopoverPrimitive.Popup.Props & Pick<PopoverPrimitive.Positioner.Props, "sideOffset" | "side" | "align" | "anchor">) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Positioner className="isolate z-50 outline-none" sideOffset={sideOffset} side={side} align={align} anchor={anchor}>
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          className={cn(
            "z-50 rounded-lg border border-border bg-popover [--surface:var(--popover)] p-4 text-sm text-popover-foreground shadow-lg outline-none",
            "data-open:animate-in data-open:fade-in-0 origin-(--transform-origin) data-open:zoom-in-95 data-open:duration-base data-open:ease-overshoot data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-99 data-closed:duration-fast data-closed:ease-exit",
            className
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  )
}

/** Closes the popover it sits in — render it as an icon button for an ×, or around Cancel/Apply. */
function PopoverClose({ ...props }: PopoverPrimitive.Close.Props) {
  return <PopoverPrimitive.Close data-slot="popover-close" {...props} />
}

export { Popover, PopoverTrigger, PopoverContent, PopoverClose }

"use client"

import { Switch as SwitchPrimitive } from "@base-ui/react/switch"
import { cn } from "@/lib/utils"
import { Loader2 } from "lucide-react"
import * as React from "react"

/**
 * Base UI renders a hidden native <input> next to the visible control and gives it no name.
 * It is aria-hidden, but page checkers still list it as an unlabelled form control, so the
 * control's aria-label / aria-labelledby is mirrored onto it.
 */
function useNamedHiddenInput(inputRef: React.Ref<HTMLInputElement> | undefined, label?: string, labelledBy?: string) {
  return React.useCallback(
    (node: HTMLInputElement | null) => {
      if (node) {
        if (label) node.setAttribute("aria-label", label)
        else node.removeAttribute("aria-label")
        if (labelledBy) node.setAttribute("aria-labelledby", labelledBy)
        else node.removeAttribute("aria-labelledby")
      }
      if (typeof inputRef === "function") inputRef(node)
      else if (inputRef) (inputRef as React.RefObject<HTMLInputElement | null>).current = node
    },
    [inputRef, label, labelledBy]
  )
}

// Figma Appearance: Brand (default) fills the checked track with the brand colour, Neutral with the
// inverse surface (black in light, white in dark; the thumb flips with it), Muted with the quiet grey.
// Brand darkens on hover (brand-700) and pressed (brand-800), the fixed tokens of the primary button; an
// unchecked track gets the control rim on hover and dark-500 pressed. Disabled is the rest look at 40 % opacity.
const SWITCH_APPEARANCE_TRACK = {
  brand: "hover:data-checked:bg-(--brand-700) active:data-checked:bg-(--brand-800)",
  neutral: "data-checked:bg-inverse",
  muted: "data-checked:bg-muted-foreground",
} as const

const SWITCH_APPEARANCE_THUMB = {
  brand: "dark:data-checked:bg-primary-foreground",
  neutral: "data-checked:bg-text-inverse",
  muted: "",
} as const

function Switch({
  className,
  size = "default",
  appearance = "brand",
  saving = false,
  inputRef,
  readOnly,
  ...props
}: SwitchPrimitive.Root.Props & {
  size?: "sm" | "default"
  /** Checked-track colour: `brand`, `neutral` (inverse black/white) or `muted` (quiet grey). */
  appearance?: keyof typeof SWITCH_APPEARANCE_TRACK
  /** Pending save: the handle shows a spinner, the switch is `aria-busy` and ignores clicks until it is cleared. */
  saving?: boolean
}) {
  const namedInputRef = useNamedHiddenInput(inputRef, props["aria-label"], props["aria-labelledby"])
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      inputRef={namedInputRef}
      data-size={size}
      data-appearance={appearance}
      data-saving={saving ? "" : undefined}
      aria-busy={saving || undefined}
      readOnly={saving || readOnly}
      className={cn(
        "peer group/switch relative inline-flex shrink-0 items-center rounded-full border border-transparent transition duration-fast ease-entrance outline-none group-has-[:focus-visible]/field-label:border-transparent group-has-[:focus-visible]/field-label:ring-0 after:absolute after:-inset-x-3 after:-inset-y-2 focus-ring aria-invalid:border-error aria-invalid:focus-ring-error data-[size=default]:h-[18px] data-[size=default]:w-8 data-[size=default]:[--switch-travel:14px] data-[size=sm]:h-3.5 data-[size=sm]:w-6 data-[size=sm]:[--switch-travel:10px] data-checked:bg-primary data-unchecked:bg-dark-400 hover:data-unchecked:border-border-control active:data-unchecked:bg-dark-500 data-disabled:cursor-not-allowed data-disabled:opacity-40",
        SWITCH_APPEARANCE_TRACK[appearance],
        saving && "cursor-progress",
        className
      )}
      {...props}
    >
      {/* M13: a transition with the overshoot curve still swings past the end and settles,
          but a second click reverses it from wherever it is instead of replaying keyframes. */}
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(
          "pointer-events-none flex items-center justify-center rounded-full bg-background ring-0 transition-transform duration-base ease-overshoot group-data-[size=default]/switch:size-4 group-data-[size=sm]/switch:size-3 data-checked:translate-x-(--switch-travel) group-data-[size=default]/switch:data-unchecked:translate-x-0 group-data-[size=sm]/switch:data-unchecked:translate-x-0 dark:data-unchecked:bg-foreground",
          SWITCH_APPEARANCE_THUMB[appearance]
        )}
      >
        {/* The spinner turns while a save runs; reduced motion keeps it as a still glyph. */}
        {saving && (
          <Loader2
            data-slot="switch-spinner"
            aria-hidden
            className="size-2.5 animate-spin text-dark-400 group-data-[size=sm]/switch:size-2 motion-reduce:animate-none"
          />
        )}
      </SwitchPrimitive.Thumb>
    </SwitchPrimitive.Root>
  )
}

export { Switch }

"use client"

import * as React from "react"
import { Heart, Star } from "lucide-react"
import { cn } from "@/lib/utils"

type RatingType = "stars" | "hearts" | "emojis" | "scale"
type RatingLabel = "none" | "left" | "right" | "tooltip"

const EMOJIS = ["😍", "🙂", "😐", "🙁", "😡"]

/** Shortest form of a value: 3.5 stays 3.5, 4 stays 4, 3.25 becomes 3.3. */
function formatValue(value: number) {
  return String(Math.round(value * 10) / 10)
}

/**
 * Rating — mirrors the Figma Rating set (Type × Value × Label).
 * - `stars` / `hearts`: fill `value` of `max` icons (yellow / pink).
 * - `emojis`: single-select reaction 1–5 (😍 🙂 😐 🙁 😡), 0 = none.
 * - `scale`: 0–10 NPS row, the selected number is filled. On narrow containers the cells shrink down to 32 px and wrap into two rows below 352 px.
 * `label` shows the value beside the rating or as a tooltip above it. `tooltip` shows a dark bubble with an arrow on the rated option.
 *
 * Interactive, it is a radio group: one Tab stop (the checked option, or the
 * first), ←/→/↑/↓ move and select, Home/End jump to the ends. `readOnly`
 * renders one image whose name carries the value ("Rated 3.5 out of 5").
 */
function Rating({
  value,
  onValueChange,
  max,
  type = "stars",
  label = "none",
  readOnly = false,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
}: {
  value: number
  onValueChange?: (value: number) => void
  max?: number
  type?: RatingType
  label?: RatingLabel
  readOnly?: boolean
  className?: string
  /** Names the group ("Rating" by default); read-only, it replaces "Rated 3.5 out of 5". */
  "aria-label"?: string
  /** Id of a visible label that names the group, instead of `aria-label`. */
  "aria-labelledby"?: string
}) {
  const [hover, setHover] = React.useState<number | null>(null)
  const optionRefs = React.useRef<(HTMLButtonElement | null)[]>([])
  const display = readOnly ? value : (hover ?? value)
  const count = type === "emojis" ? EMOJIS.length : (max ?? (type === "scale" ? 11 : 5))
  const text = type === "scale" || type === "emojis" ? String(value) : `${value.toFixed(1)}`

  // Option values: stars, hearts and emojis 1…n, the scale 0…n-1.
  const first = type === "scale" ? 0 : 1
  const last = type === "scale" ? count - 1 : count
  // 0 means "nothing chosen" for stars, hearts and emojis; on the scale 0 is an answer.
  const hasChecked = type === "scale" ? value >= first && value <= last : value >= 1
  // A fractional value (3.5) has no exact option: the nearest one is checked.
  const checkedValue = Math.min(last, Math.max(first, Math.round(value)))
  const tabStop = hasChecked ? checkedValue : first
  const tooltipTarget = checkedValue

  const optionLabel = (v: number) =>
    type === "stars" ? `${v} of ${count} stars` : type === "hearts" ? `${v} of ${count} hearts` : undefined

  function select(next: number) {
    const clamped = Math.min(last, Math.max(first, next))
    onValueChange?.(clamped)
    optionRefs.current[clamped - first]?.focus()
  }

  // Arrows move and select (no wrap at the ends), Home/End jump; mirrored in RTL.
  function handleKeyDown(e: React.KeyboardEvent<HTMLButtonElement>, current: number) {
    const rtl = e.currentTarget.closest("[dir=rtl]") != null
    let next: number | null = null
    if (e.key === (rtl ? "ArrowLeft" : "ArrowRight") || e.key === "ArrowUp") next = current + 1
    else if (e.key === (rtl ? "ArrowRight" : "ArrowLeft") || e.key === "ArrowDown") next = current - 1
    else if (e.key === "Home") next = first
    else if (e.key === "End") next = last
    if (next === null) return
    e.preventDefault()
    select(next)
  }

  const labelNode =
    label === "none" || label === "tooltip" ? null : (
      <span className="text-sm font-medium tabular-nums text-foreground">{text}</span>
    )

  /** One option: a radio in the group, or a plain span when read-only. */
  function option(
    v: number,
    className: string,
    children: React.ReactNode,
    handlers: Pick<React.ButtonHTMLAttributes<HTMLButtonElement>, "onClick" | "onMouseEnter" | "onMouseLeave">,
    name?: string
  ) {
    const optionClassName = cn(className, "relative")
    const bubble =
      label === "tooltip" && v === tooltipTarget ? (
        <span aria-hidden="true" data-slot="rating-bubble" className="pointer-events-none absolute bottom-full left-1/2 z-10 mb-1.5 -translate-x-1/2">
          <span className="inline-flex h-6 items-center whitespace-nowrap rounded-md bg-neutral-dark-content px-2 text-xs font-medium leading-none text-neutral-white shadow-md">{text}</span>
          <svg width="10" height="5" viewBox="0 0 10 5" fill="none" className="absolute left-1/2 top-full -translate-x-1/2">
            <path d="M0 0L5 5L10 0Z" className="fill-neutral-dark-content" />
          </svg>
        </span>
      ) : null

    if (readOnly) {
      return (
        <span key={v} className={optionClassName}>
          {children}
          {bubble}
        </span>
      )
    }
    return (
      <button
        key={v}
        ref={(el) => {
          optionRefs.current[v - first] = el
        }}
        type="button"
        role="radio"
        aria-checked={hasChecked && v === checkedValue}
        aria-label={name}
        tabIndex={v === tabStop ? 0 : -1}
        onKeyDown={(e) => handleKeyDown(e, v)}
        className={optionClassName}
        {...handlers}
      >
        {children}
        {bubble}
      </button>
    )
  }

  let items: React.ReactNode
  if (type === "stars" || type === "hearts") {
    const Icon = type === "stars" ? Star : Heart
    items = Array.from({ length: count }).map((_, i) => {
      // Rounded, so 3.2 fills three stars and 4.5 five (it filled four and five before: any fraction rounded up).
      const filled = i < Math.round(display)
      return option(
        i + 1,
        "grid size-6 place-items-center rounded-sm outline-none focus-ring",
        <Icon aria-hidden className={cn("size-4", filled ? (type === "stars" ? "fill-brand-quaternary text-brand-quaternary" : "fill-brand-tertiary text-brand-tertiary") : "fill-none text-border-control")} />,
        { onMouseEnter: () => setHover(i + 1), onMouseLeave: () => setHover(null), onClick: () => select(i + 1) },
        optionLabel(i + 1)
      )
    })
  } else if (type === "emojis") {
    items = EMOJIS.map((emoji, i) => {
      const selected = value === i + 1
      return option(
        i + 1,
        cn("flex size-12 items-center justify-center rounded-md border text-xl transition-colors duration-fast ease-entrance outline-none focus-ring", selected ? "border-tint-text-indigo bg-tint-indigo" : cn("border-transparent bg-background", !readOnly && "hover:bg-subtle")),
        emoji,
        // Clicking the chosen face again clears it (0 = none), as before.
        { onClick: () => onValueChange?.(selected ? 0 : i + 1) },
        emoji
      )
    })
  } else {
    items = Array.from({ length: count }).map((_, i) => {
      const selected = value === i
      return option(
        i,
        cn("flex h-10 w-full min-w-8 items-center justify-center rounded-md text-xs font-semibold tabular-nums transition-colors duration-base ease-entrance outline-none focus-ring", selected ? "bg-primary text-primary-foreground" : cn("bg-background text-text-secondary", !readOnly && "hover:bg-subtle hover:text-foreground")),
        i,
        { onClick: () => onValueChange?.(i) }
      )
    })
  }

  const groupClassName = type === "scale"
    ? "grid grid-cols-6 gap-1 @min-[352px]:grid-cols-11 @min-[352px]:gap-0 @min-[392px]:gap-1"
    : cn("flex items-center", type === "emojis" ? "gap-2" : "gap-0")
  const rootClassName = cn(
    "relative inline-flex items-center",
    type === "emojis" ? "gap-2" : type === "scale" ? "gap-1 max-w-full" : "gap-0.5",
    label === "left" || label === "right" ? "gap-2.5" : "",
    className
  )

  const group = (
    <div className={groupClassName}>{items}</div>
  )
  const scaleGroup = type === "scale" ? (
    <div className="@container w-[480px] min-w-0 max-w-full">{group}</div>
  ) : group

  if (readOnly) {
    // One image for assistive tech; the stars and the visible label are its picture.
    return (
      <div
        data-slot="rating"
        role="img"
        aria-label={ariaLabel ?? `Rated ${formatValue(value)} out of ${type === "scale" ? last : count}`}
        aria-labelledby={ariaLabelledBy}
        className={rootClassName}
      >
        {label === "left" && labelNode}
        {scaleGroup}
        {label === "right" && labelNode}
      </div>
    )
  }

  return (
    <div data-slot="rating" className={rootClassName}>
      {label === "left" && labelNode}
      {type === "scale" ? (
        <div className="@container w-[480px] min-w-0 max-w-full">
          <div
            role="radiogroup"
            aria-label={ariaLabelledBy ? undefined : (ariaLabel ?? "Rating")}
            aria-labelledby={ariaLabelledBy}
            className={groupClassName}
          >
            {items}
          </div>
        </div>
      ) : (
        <div
          role="radiogroup"
          aria-label={ariaLabelledBy ? undefined : (ariaLabel ?? "Rating")}
          aria-labelledby={ariaLabelledBy}
          className={groupClassName}
        >
          {items}
        </div>
      )}
      {label === "right" && labelNode}
    </div>
  )
}

export { Rating }
export type { RatingType, RatingLabel }

